  test('notebook shelf transactions cap concurrent snapshots and reject corrupt exact-source content before replacement', async ({ page }) => {
    const result=await page.evaluate(async()=>{const lib=await import('/src/utils/notebookShelf.js'),flight=await import('/src/utils/flightLog.js');await new Promise((resolve,reject)=>{const r=indexedDB.deleteDatabase('skydash-private-notebook-shelf');r.onsuccess=resolve;r.onerror=reject;});const log={filename:'synthetic.csv',model_version:flight.LOG_VERSION,csv_text:flight.SAMPLE_LOG,sha256:await flight.flightCSVHash(flight.SAMPLE_LOG),samples:flight.parseFlightCSV(flight.SAMPLE_LOG)},entries=[{id:'a',first_row:3,last_row:5,label:'Saved A',notes:'Private'}];const writes=await Promise.allSettled(Array.from({length:12},()=>lib.saveNotebookBundle(log,entries))),listed=await lib.listNotebookBundles(),chosen=listed[0];let rejected=false;await new Promise((resolve,reject)=>{const r=indexedDB.open('skydash-private-notebook-shelf',1);r.onsuccess=()=>{const db=r.result,tx=db.transaction('bundles','readwrite'),store=tx.objectStore('bundles'),get=store.get(chosen.id);get.onsuccess=()=>{const record=get.result,data=JSON.parse(record.contents);data.source.csv_text+='\n';record.contents=JSON.stringify(data);store.put(record);};tx.oncomplete=()=>{db.close();resolve();};tx.onerror=reject;};r.onerror=reject;});try{await lib.readNotebookBundle(chosen.id);}catch(error){rejected=error.message.includes('fingerprint mismatch');}const count=(await lib.listNotebookBundles()).length;await lib.deleteNotebookBundle(chosen.id);const remaining=(await lib.listNotebookBundles()).length;await new Promise((resolve,reject)=>{const r=indexedDB.deleteDatabase('skydash-private-notebook-shelf');r.onsuccess=resolve;r.onerror=reject;});return{fulfilled:writes.filter(x=>x.status==='fulfilled').length,rejected:writes.filter(x=>x.status==='rejected').length,count,corruptRejected:rejected,remaining};});expect(result).toEqual({fulfilled:10,rejected:2,count:10,corruptRejected:true,remaining:9});
  });

  test('notebook shelf aggregate byte limits and corrupt metadata reject without overwriting committed bundles', async ({ page }) => {
    const result=await page.evaluate(async()=>{const lib=await import('/src/utils/notebookShelf.js'),flight=await import('/src/utils/flightLog.js');const reset=()=>new Promise((resolve,reject)=>{const r=indexedDB.deleteDatabase('skydash-private-notebook-shelf');r.onsuccess=resolve;r.onerror=reject;});await reset();const csv='time_s,latitude,longitude,altitude_m,ground_speed_m_s,battery_pct\n0,28,77,'+'\t'.repeat(900000)+'1,0,99\n1,28,77,2,0,98\n',log={filename:'synthetic-large.csv',model_version:flight.LOG_VERSION,csv_text:csv,sha256:await flight.flightCSVHash(csv),samples:flight.parseFlightCSV(csv)},entries=[{id:'a',first_row:1,last_row:2,label:'Large exact bundle',notes:''}];const writes=await Promise.allSettled(Array.from({length:6},()=>lib.saveNotebookBundle(log,entries))),listed=await lib.listNotebookBundles(),total=listed.reduce((sum,x)=>sum+x.bytes,0);const chosen=listed[0];await new Promise((resolve,reject)=>{const r=indexedDB.open('skydash-private-notebook-shelf',1);r.onsuccess=()=>{const db=r.result,tx=db.transaction('bundles','readwrite'),store=tx.objectStore('bundles'),get=store.get(chosen.id);get.onsuccess=()=>store.put({...get.result,title:'Metadata mismatch'});tx.oncomplete=()=>{db.close();resolve();};tx.onerror=reject;};r.onerror=reject;});let mismatch=false;try{await lib.readNotebookBundle(chosen.id);}catch(error){mismatch=error.message.includes('metadata does not match');}const count=(await lib.listNotebookBundles()).length;await reset();return{success:writes.filter(x=>x.status==='fulfilled').length,rejected:writes.filter(x=>x.status==='rejected').length,totalWithinCap:total<=10*1024*1024,count,metadataRejected:mismatch,byteFailure:writes.some(x=>x.status==='rejected'&&x.reason.message.includes('10MiB'))};});expect(result).toEqual({success:5,rejected:1,totalWithinCap:true,count:5,metadataRejected:true,byteFailure:true});
  });

